@implementation WPSideDockView
- (instancetype)initWithFrame:(CGRect)f{if((self=[super initWithFrame:f])){self.backgroundColor=FZColor(@"WPPulse_BgColor",[UIColor colorWithWhite:0.9 alpha:.9]);self.layer.cornerRadius=18;self.layer.shadowColor=FZColor(@"WPPulse_ShadowColor",FZDefaultShadow()).CGColor;self.layer.shadowOpacity=.7;self.layer.shadowRadius=10;self.layer.shadowOffset=CGSizeMake(0,3);self.layer.masksToBounds=NO;}return self;}
