- (void)handleDockLong:(UILongPressGestureRecognizer*)g{if(g.state==UIGestureRecognizerStateBegan&&self.owner.navigationController)[self.owner.navigationController pushViewController:[WPCustomSettingsPanel new] animated:YES];}
@end

